(7543083, 1207589, 50695, '<td valign="top">You''ve captured a sadness that she may not even have been feeling, or didn''t know she was feeling. But it is through her and all around her.<br/> <br/>I''m hanging this in my fantasy gallery<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1077279" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg"/></a></td>', 'You''ve captured a sadness that she may not even have been feeling, or didn''t know she was feeling. But it is through her and all around her. I''m hanging this in my fantasy gallery ', '2017-11-07 14:36:57.000000', NULL, 1),
(7543085, 1207123, 50695, '<td valign="top">John Berger would love this</td>', 'John Berger would love this', '2017-11-07 14:37:34.000000', NULL, 1),
(7543086, 1207149, 50695, '<td valign="top">I was turned off at first by the seemingly haphazard framing, but actually it''s quite dynamic and funny. There''s a weird halo around her face. This might want more subtle processing</td>', 'I was turned off at first by the seemingly haphazard framing, but actually it''s quite dynamic and funny. There''s a weird halo around her face. This might want more subtle processing', '2017-11-07 14:37:43.000000', NULL, 1),
